function mapBreak(){const sample=visible.filter(item=>item.coordinates).slice(0,18);const bounds={west:14.18,east:14.62,south:35.79,north:36.09};const dots=sample.map(item=>{const x=8+(item.coordinates[0]-bounds.west)/(bounds.east-bounds.west)*84,y=92-(item.coordinates[1]-bounds.south)/(bounds.north-bounds.south)*84;return `<i class="map-dot" style="left:${Math.max(5,Math.min(95,x))}%;top:${Math.max(5,Math.min(95,y))}%" title="${escapeHTML(item.area)}"></i>`;}).join('');return `<section class="market-map-break"><div class="mini-map" aria-label="Approximate locations of current homes">${dots}</div><div class="map-break-copy"><span>YOUR SEARCH, IN SPACE</span><h3>See what surrounds every home.</h3><p>Nexus Housing stays fast. Nexus Link adds the full map, recurring journeys and verified lifestyle context.</p><button type="button" data-matrix>Explore in Nexus Link ↗</button></div></section>`;}
function topVillages(){const counts=new Map();for(const property of visible)counts.set(property.area,(counts.get(property.area)||0)+1);return [...counts].sort((a,b)=>b[1]-a[1]).slice(0,3);}
function villageStrip(){const villages=topVillages();if(!villages.length)return '';return `<section class="village-strip" aria-label="Village guides">${villages.map(([name,count])=>`<button type="button" class="village-card" data-village="${escapeHTML(name)}"><span>VILLAGE BROCHURE · ${count} ${count===1?'HOME':'HOMES'}</span><h3>${escapeHTML(name)}</h3><p>Open the 2 km place radius, daily essentials and local character.</p><b>↗</b></button>`).join('')}</section>`;}
function recentTime(property){const time=new Date(property.updatedAt||0).getTime();return Number.isFinite(time)?time:0;}
function isLuxury(property){const text=`${property.title} ${property.description} ${property.features.join(' ')}`.toLowerCase();return /luxury|premium|designer|penthouse|tigne|portomaso|seafront|sea view/.test(text)||(property.rent!==null&&property.rent>=3000);}
