function aestheticScore(property){return (property.reviewedScene?120:0)+(isLuxury(property)?32:0)+(property.features.includes('Sea view')?18:0)+(property.features.includes('Seafront')?20:0)+(property.features.includes('Terrace')?9:0)+(property.features.includes('Pool')?9:0)+Math.min(property.images.length,12);}
