function renderConnectorPlaces(connector){if(!connector?.places.length)return `${connector?.key==='mobility'?mobilityReferencePanel():''}<div class="connector-empty"><b>UNKNOWN</b><span>No verified nearby places are connected in this category yet.</span></div>`;return `${connector.key==='mobility'?mobilityReferencePanel():''}${connector.places.slice(0,6).map(renderPlaceEvidence).join('')}`;}
let propertyMap=null,mapGeneration=0,selectedMapPlace=null,routeMode='walk',routeGeneration=0,mapTask=Promise.resolve();
const routingCache=new Map();
function renderPropertyMap(property,intelligence,activeKey='swimming'){
 return `<div class="intelligence-map real-map" data-active-connector="${escapeHTML(activeKey)}"><div class="property-tile-map" aria-label="Interactive neighbourhood map"></div><div class="map-toolbar"><div><button type="button" data-route-mode="walk" aria-pressed="true">Walk</button><button type="button" data-route-mode="car" aria-pressed="false">Drive</button></div><button type="button" data-map-home aria-label="Return to this property">⌖</button></div><div class="map-evidence"><span class="property-anchor-label">${intelligence.precision==='AREA_ONLY'?'AROUND THIS AREA':'APPROXIMATE HOME LOCATION'}</span><b data-route-status>Calculating walking & driving routes…</b><small data-map-route-note>Exact places · approximate home pin</small></div></div>`;
}
