 const generation=++mapGeneration;
 mapTask=mapTask.catch(()=>{}).then(async()=>{
 if(generation!==mapGeneration)return;propertyMap?.destroy();propertyMap=null;
 const element=$('#property-drawer .property-tile-map');if(!element)return;
 try{const mounted=await createPropertyMap(element,intelligence,{onSelect:id=>focusMappedPlace(id)});if(generation!==mapGeneration){mounted?.destroy();return;}propertyMap=mounted;const key=$('.intelligence-map')?.dataset.activeConnector;propertyMap?.select(key,connectorByKey(intelligence,key).places);}
 catch{if($('[data-route-status]'))$('[data-route-status]').textContent='Map unavailable · connections listed alongside';}
 });return mapTask;
